import { useEffect } from 'react';

import { FetchBaseQueryError } from '@reduxjs/toolkit/query/react';
import { SerializedError } from '@reduxjs/toolkit/react';

export const useNotFoundError = (error: FetchBaseQueryError | SerializedError | undefined) => {
	const status =
		error && 'originalStatus' in error ? error.originalStatus : error && 'status' in error ? error.status : -1;

	useEffect(() => {
		if (status === 404) {
			throw new Response('Not Found', { status: 404 });
		}
	}, [status]);
};
